<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Producer Audio Review Console V12 */
function tuff_beatz_producer_audio_console_files($id){$out=array();if(!function_exists('tuff_beatz_vault_files'))return $out;foreach(tuff_beatz_vault_files($id) as $f){$ext=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));if(!in_array($ext,array('wav','aiff','aif','mp3','m4a'),true))continue;$out[]=array('id'=>$f['id']??'','name'=>$f['name']??'Audio File','version'=>$f['version']??'','category'=>$f['category']??'source','size'=>function_exists('tuff_beatz_vault_human_size')?tuff_beatz_vault_human_size($f['size']??0):'','uploaded_at'=>$f['uploaded_at']??'','stream'=>function_exists('tuff_beatz_vault_stream_url')?tuff_beatz_vault_stream_url($id,$f['id']):'','download'=>function_exists('tuff_beatz_vault_download_url')?tuff_beatz_vault_download_url($id,$f['id']):'');}return array_reverse($out);}
function tuff_beatz_producer_audio_console_assets(){if(!is_page('producer-portal'))return;$p=get_template_directory().'/assets/css/producer-audio-console.css';if(file_exists($p))wp_enqueue_style('tuff-beatz-producer-audio-console',get_template_directory_uri().'/assets/css/producer-audio-console.css',array('tuff-beatz-producer-command-v2'),filemtime($p));}
add_action('wp_enqueue_scripts','tuff_beatz_producer_audio_console_assets',95);
function tuff_beatz_render_producer_audio_console(){if(!is_page('producer-portal')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>100,'fields'=>'ids'));$map=array();foreach($q->posts as $id){if(!current_user_can('edit_post',$id))continue;$files=tuff_beatz_producer_audio_console_files($id);$map[(string)$id]=array('title'=>get_the_title($id),'status'=>get_post_meta($id,'_tb_request_status',true)?:'new','files'=>$files,'workspace'=>function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id).'#review':'');}wp_reset_postdata();?><script>document.addEventListener('DOMContentLoaded',function(){var map=<?php echo wp_json_encode($map);?>;function esc(s){return String(s||'').replace(/[&<>'"]/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[c];});}document.querySelectorAll('.tb-producer-row').forEach(function(row){var link=row.querySelector('a[href*="project-dashboard"][href*="project="]');if(!link)return;var m=link.href.match(/[?&]project=(\d+)/);if(!m||!map[m[1]])return;var d=map[m[1]],actions=row.querySelector('.tb-producer-actions');if(!actions)return;var btn=document.createElement('button');btn.type='button';btn.className='tb-audio-console-open';btn.innerHTML='<span>♫</span> Audio Console <b>'+d.files.length+'</b>';actions.appendChild(btn);var panel=document.createElement('section');panel.className='tb-producer-audio-console';panel.hidden=true;var html='<div class="tb-pac-head"><div><small>PRODUCER AUDIO REVIEW</small><h3>'+esc(d.title)+'</h3></div><div><span>'+esc(d.status.replace(/-/g,' '))+'</span><button type="button" class="tb-pac-close" aria-label="Close">×</button></div></div>';if(d.files.length){html+='<div class="tb-pac-list">';d.files.forEach(function(f,i){html+='<article class="tb-pac-track"><div class="tb-pac-track-head"><div><span>'+(f.category==='delivery'?'REVIEW / DELIVERY':'SOURCE AUDIO')+'</span><strong>'+esc(f.version||f.name)+'</strong><small>'+esc(f.name)+' • '+esc(f.size)+'</small></div><a href="'+f.download+'">Download ↓</a></div><audio controls preload="metadata" src="'+f.stream+'"></audio></article>';});html+='</div>';}else{html+='<div class="tb-pac-empty"><strong>No audio in the Private Vault yet.</strong><p>Upload source audio, mixes or masters and they will appear here automatically.</p></div>';}if(d.workspace)html+='<div class="tb-pac-footer"><a href="'+d.workspace+'">Open Full Mix Review Workspace →</a></div>';panel.innerHTML=html;row.insertAdjacentElement('afterend',panel);btn.addEventListener('click',function(){document.querySelectorAll('.tb-producer-audio-console').forEach(function(x){if(x!==panel){x.hidden=true;x.querySelectorAll('audio').forEach(function(a){a.pause();});}});panel.hidden=!panel.hidden;if(panel.hidden)panel.querySelectorAll('audio').forEach(function(a){a.pause();});});panel.querySelector('.tb-pac-close').addEventListener('click',function(){panel.hidden=true;panel.querySelectorAll('audio').forEach(function(a){a.pause();});});panel.querySelectorAll('audio').forEach(function(a){a.addEventListener('play',function(){document.querySelectorAll('.tb-producer-audio-console audio').forEach(function(other){if(other!==a)other.pause();});});});});});</script><?php }
add_action('wp_footer','tuff_beatz_render_producer_audio_console',18);
